#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    int R, C, Q;
    stringstream(line) >> R >> C >> Q;
    vector<string> g(R);
    for (auto &row : g) {
        getline(cin, row);
        if (!row.empty() && row.back() == '\r') row.pop_back();
        row.resize(C, ' ');  // spaces are roads
    }
    // Multi-source BFS from every warehouse.
    vector<int> d(R * C, -1), q;
    q.reserve(R * C);
    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++)
            if (g[i][j] == 'D') d[i * C + j] = 0, q.push_back(i * C + j);
    const int di[4] = {1, -1, 0, 0}, dj[4] = {0, 0, 1, -1};
    for (size_t h = 0; h < q.size(); h++) {
        int i = q[h] / C, j = q[h] % C;
        for (int k = 0; k < 4; k++) {
            int x = i + di[k], y = j + dj[k];
            if (x >= 0 && x < R && y >= 0 && y < C && g[x][y] != 'X' && d[x * C + y] < 0) {
                d[x * C + y] = d[q[h]] + 1;
                q.push_back(x * C + y);
            }
        }
    }
    string out;
    for (int k = 0; k < Q; k++) {
        long long i, j;
        cin >> i >> j;
        if (k) out += ' ';
        out += to_string(i >= 0 && i < R && j >= 0 && j < C ? d[i * C + j] : -1);
    }
    cout << out << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int R = Integer.parseInt(st.nextToken()), C = Integer.parseInt(st.nextToken()), Q = Integer.parseInt(st.nextToken());
        char[][] g = new char[R][C];
        for (int i = 0; i < R; i++) {
            String row = br.readLine();
            if (row == null) row = "";
            Arrays.fill(g[i], ' ');
            for (int j = 0; j < Math.min(C, row.length()); j++) g[i][j] = row.charAt(j);
        }
        // Multi-source BFS from every warehouse.
        int[] d = new int[R * C], q = new int[R * C];
        Arrays.fill(d, -1);
        int tail = 0;
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++)
                if (g[i][j] == 'D') {
                    d[i * C + j] = 0;
                    q[tail++] = i * C + j;
                }
        int[] di = {1, -1, 0, 0}, dj = {0, 0, 1, -1};
        for (int h = 0; h < tail; h++) {
            int i = q[h] / C, j = q[h] % C;
            for (int k = 0; k < 4; k++) {
                int x = i + di[k], y = j + dj[k];
                if (x >= 0 && x < R && y >= 0 && y < C && g[x][y] != 'X' && d[x * C + y] < 0) {
                    d[x * C + y] = d[q[h]] + 1;
                    q[tail++] = x * C + y;
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        st = new StringTokenizer("");
        for (int k = 0; k < Q; k++) {
            while (!st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            long i = Long.parseLong(st.nextToken());
            while (!st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            long j = Long.parseLong(st.nextToken());
            if (k > 0) sb.append(' ');
            sb.append(i >= 0 && i < R && j >= 0 && j < C ? d[(int) i * C + (int) j] : -1);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(string(data), "\n")
	head := strings.Fields(lines[0])
	R, _ := strconv.Atoi(head[0])
	C, _ := strconv.Atoi(head[1])
	Q, _ := strconv.Atoi(head[2])
	g := make([][]byte, R)
	for i := 0; i < R; i++ {
		row := []byte(strings.TrimSuffix(lines[1+i], "\r"))
		g[i] = make([]byte, C)
		for j := range g[i] {
			g[i][j] = ' '
			if j < len(row) {
				g[i][j] = row[j]
			}
		}
	}
	// Multi-source BFS from every warehouse.
	d := make([]int, R*C)
	q := make([]int, 0, R*C)
	for i := range d {
		d[i] = -1
	}
	for i := 0; i < R; i++ {
		for j := 0; j < C; j++ {
			if g[i][j] == 'D' {
				d[i*C+j] = 0
				q = append(q, i*C+j)
			}
		}
	}
	di, dj := [4]int{1, -1, 0, 0}, [4]int{0, 0, 1, -1}
	for h := 0; h < len(q); h++ {
		i, j := q[h]/C, q[h]%C
		for k := 0; k < 4; k++ {
			x, y := i+di[k], j+dj[k]
			if x >= 0 && x < R && y >= 0 && y < C && g[x][y] != 'X' && d[x*C+y] < 0 {
				d[x*C+y] = d[q[h]] + 1
				q = append(q, x*C+y)
			}
		}
	}
	rest := strings.Fields(strings.Join(lines[1+R:], " "))
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for k := 0; k < Q; k++ {
		i, _ := strconv.Atoi(rest[2*k])
		j, _ := strconv.Atoi(rest[2*k+1])
		if k > 0 {
			w.WriteByte(' ')
		}
		if i >= 0 && i < R && j >= 0 && j < C {
			w.WriteString(strconv.Itoa(d[i*C+j]))
		} else {
			w.WriteString("-1")
		}
	}
	w.WriteByte('\n')
}
